"""Qwen3 ForcedAligner (-hf) word/char timestamps via TokenClassification."""

from __future__ import annotations

import logging
from typing import Any

_log = logging.getLogger("transub_engine.asr.qwen3_hf_align")


class _TsItem:
    __slots__ = ("text", "start_time", "end_time", "start", "end", "word")

    def __init__(self, text: str, start: float, end: float) -> None:
        self.text = text
        self.word = text
        self.start_time = float(start)
        self.end_time = float(end)
        self.start = float(start)
        self.end = float(end)


def _normalize_timestamp_rows(rows: Any) -> list[_TsItem]:
    out: list[_TsItem] = []
    if not rows:
        return out
    if isinstance(rows, dict):
        rows = [rows]
    for row in rows:
        if isinstance(row, dict):
            text = str(row.get("text") or row.get("word") or "").strip()
            start = float(row.get("start_time", row.get("start", 0)) or 0)
            end = float(row.get("end_time", row.get("end", start)) or start)
        else:
            text = str(
                getattr(row, "text", None) or getattr(row, "word", None) or ""
            ).strip()
            start = float(
                getattr(row, "start_time", None) or getattr(row, "start", 0) or 0
            )
            end = float(
                getattr(row, "end_time", None) or getattr(row, "end", start) or start
            )
        if not text:
            continue
        out.append(_TsItem(text, start, max(end, start)))
    return out


def align_transcript(
    bundle: Any,
    *,
    audio: Any,
    transcript: str,
    language: str | None,
) -> list[_TsItem]:
    """Run ForcedAligner on one clip; return timestamp items compatible with cue builders."""
    text = str(transcript or "").strip()
    if not text or not bundle or not getattr(bundle, "has_aligner", False):
        return []

    import torch

    aligner_processor = bundle.aligner_processor
    aligner_model = bundle.aligner_model
    lang = language or "English"

    try:
        aligner_inputs, word_lists = aligner_processor.prepare_forced_aligner_inputs(
            audio=audio,
            transcript=text,
            language=lang,
        )
    except Exception as err:
        _log.warning("ForcedAligner prepare failed: %s", err)
        return []

    try:
        if hasattr(aligner_inputs, "to"):
            aligner_inputs = aligner_inputs.to(aligner_model.device, bundle.dtype)
    except Exception:
        try:
            aligner_inputs = aligner_inputs.to(aligner_model.device)
        except Exception:
            pass

    try:
        with torch.inference_mode():
            outputs = aligner_model(**aligner_inputs)
        ts_token = getattr(getattr(aligner_model, "config", None), "timestamp_token_id", None)
        kwargs: dict[str, Any] = {
            "logits": outputs.logits,
            "input_ids": aligner_inputs["input_ids"],
            "word_lists": word_lists,
        }
        if ts_token is not None:
            kwargs["timestamp_token_id"] = ts_token
        decoded = aligner_processor.decode_forced_alignment(**kwargs)
    except Exception as err:
        _log.warning("ForcedAligner decode failed: %s", err)
        return []

    if isinstance(decoded, list) and decoded and isinstance(decoded[0], list):
        rows = decoded[0]
    else:
        rows = decoded
    return _normalize_timestamp_rows(rows)


def attach_time_stamps(result: Any, stamps: list[_TsItem]) -> Any:
    """Return a result-like object with ``.text`` and ``.time_stamps``."""
    text = ""
    if result is not None:
        text = str(
            getattr(result, "text", None)
            or getattr(result, "transcription", None)
            or (result.get("transcription") if isinstance(result, dict) else "")
            or ""
        ).strip()
    lang = getattr(result, "language", None) if result is not None else None

    class _Aligned:
        def __init__(self) -> None:
            self.text = text
            self.transcription = text
            self.language = lang
            self.time_stamps = stamps

    return _Aligned()
